package com.docgen.service

import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.server.Route
import akka.http.scaladsl.model._
import akka.http.scaladsl.model.headers._
import java.net.{URI, URLDecoder, URLEncoder}
import java.nio.charset.StandardCharsets
import scala.util.{Try, Success, Failure}

/**
 * PDF Generation Service - handles document rendering requests
 * Deployed behind nginx reverse proxy with X-Forwarded-Host support
 * 
 * The proxy normalizes paths and forwards to this backend service.
 * After PDF generation completes, user is redirected to the download endpoint.
 */
object PdfGenerationRoutes {

  // Trusted internal domains for redirect after PDF generation
  private val trustedDomains: Set[String] = Set(
    "docs.internal.corp",
    "cdn.internal.corp",
    "api.internal.corp"
  )

  // Safe default host used when the proxy-supplied host is not trusted
  private val defaultTrustedHost: String = "docs.internal.corp"

  // Validates that a URI's host belongs to trusted infrastructure
  private def isInternalHost(host: String): Boolean = {
    trustedDomains.exists(domain => host == domain)
  }

  // Reconstructs the canonical base URL from proxy headers.
  // The X-Forwarded-Host value is attacker-controllable, so it must be
  // validated against the trusted domain set before being used to build
  // any redirect target. Untrusted hosts fall back to a safe default.
  private def resolveBaseUrl(headers: Seq[HttpHeader]): String = {
    val scheme = headers.find(_.lowercaseName == "x-forwarded-proto")
      .map(_.value).filter(s => s == "https" || s == "http").getOrElse("https")
    val forwardedHost = headers.find(_.lowercaseName == "x-forwarded-host")
      .map(_.value)
      .filter(isInternalHost)
      .getOrElse(defaultTrustedHost)
    s"$scheme://$forwardedHost"
  }

  // Normalizes redirect path to prevent directory traversal
  private def normalizePath(path: String): String = {
    val decoded = URLDecoder.decode(path, StandardCharsets.UTF_8.name())
    val uri = new URI(decoded).normalize()
    uri.getPath match {
      case p if p == null || p.isEmpty => "/"
      case p => p
    }
  }

  /**
   * Validates the complete redirect URL.
   * Ensures the target is within our trusted domain set.
   * Called after PDF generation to redirect user to download location.
   */
  private def validateRedirectTarget(targetUrl: String, baseUrl: String): Either[String, String] = {
    Try(new URI(targetUrl)) match {
      case Success(uri) =>
        val effectiveHost = Option(uri.getHost).getOrElse {
          // Relative URL - resolve against base
          new URI(baseUrl + targetUrl).getHost
        }

        if (effectiveHost != null && isInternalHost(effectiveHost)) {
          Right(targetUrl)
        } else if (uri.getHost == null) {
          // Path-only redirect, considered safe
          Right(baseUrl + normalizePath(targetUrl))
        } else {
          Left(s"Untrusted redirect target: $effectiveHost")
        }

      case Failure(_) =>
        Left("Invalid URL format")
    }
  }

  /**
   * Computes the post-generation callback URL.
   * The 'callback' parameter specifies where to redirect after PDF is ready.
   * This is URL-encoded by the frontend before submission.
   */
  private def computeCallbackUrl(
    callbackParam: String,
    requestHeaders: Seq[HttpHeader]
  ): Either[String, String] = {
    val baseUrl = resolveBaseUrl(requestHeaders)
    val decodedCallback = URLDecoder.decode(callbackParam, StandardCharsets.UTF_8.name())

    // Single decode only - proxy encoding is handled at the proxy layer
    validateRedirectTarget(decodedCallback, baseUrl)
  }

  val routes: Route = {
    pathPrefix("api" / "v2" / "pdf") {
      path("generate") {
        post {
          parameterMap { params =>
            extractRequest { request =>
              val templateId = params.getOrElse("template", "default")
              val callbackUrl = params.get("callback")

              // Simulate PDF generation
              val pdfResult = generatePdf(templateId, params)

              callbackUrl match {
                case Some(cb) =>
                  computeCallbackUrl(cb, request.headers.toList) match {
                    case Right(validUrl) =>
                      redirect(Uri(validUrl), StatusCodes.Found)
                    case Left(error) =>
                      complete(StatusCodes.BadRequest -> s"Invalid callback: $error")
                  }
                case None =>
                  complete(StatusCodes.OK -> pdfResult)
              }
            }
          }
        }
      } ~
      path("status" / Segment) { jobId =>
        get {
          extractRequest { request =>
            val returnTo = request.headers
              .find(_.lowercaseName == "x-return-url")
              .map(_.value)

            returnTo match {
              case Some(url) =>
                val baseUrl = resolveBaseUrl(request.headers.toList)
                validateRedirectTarget(url, baseUrl) match {
                  case Right(validUrl) =>
                    redirect(Uri(validUrl), StatusCodes.Found)
                  case Left(_) =>
                    complete(StatusCodes.OK -> s"Job $jobId: completed")
                }
              case None =>
                complete(StatusCodes.OK -> s"Job $jobId: completed")
            }
          }
        }
      }
    }
  }

  private def generatePdf(templateId: String, params: Map[String, String]): String = {
    // PDF generation logic placeholder
    s"""{ "status": "complete", "template": "$templateId", "downloadUrl": "/downloads/output.pdf" }"""
  }
}
